(()=>{
  'use strict';const M=window.DistrictPreview,$=id=>document.getElementById(id);let students=M.createStudents(),grade=6,view='rows',reportId=null,lastUpdated=null;
  const schoolName=s=>s.school==='middle'?'Example Middle School':'Example High School';
  const state=()=>({grade,school:$('schoolFilter').value,search:$('studentSearch').value,filter:$('supportFilter').value,sort:$('sortBy').value});
  const filtered=()=>M.select(students,state());
  function bar(value,label,cls=''){return `<span class="progressTrack ${cls}" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><i style="width:${value}%"></i></span>`;}
  function smallPath(s,p){return `<span class="miniPath ${M.hasTrophy(s,p)?'earned':''}"><span class="miniLabel">${M.symbols[p]} ${M.names[p]}</span>${bar(M.percentage(s,p),M.names[p]+' progression')}<span class="miniValue">${M.hasTrophy(s,p)?'🏆':M.percentage(s,p)+'%'}</span></span>`;}
  function renderGrades(){const all=$('allGrades');all.textContent=grade==='all'?'Viewing all grades':'View all grades';$('gradeCards').innerHTML=Array.from({length:7},(_,i)=>i+6).map(g=>{const s=M.summary(students.filter(s=>s.grade===g));return `<button class="gradeCard ${grade===g?'selected':''}" data-grade="${g}" aria-pressed="${grade===g}"><span>GRADE ${g}</span><strong>${s.average}<small>%</small></strong>${bar(s.average,'Grade '+g+' average progression')}<span class="gradeMeta">${s.count} students · ${s.attention} need attention</span></button>`;}).join('');$('gradeCards').querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{grade=Number(b.dataset.grade);$('schoolFilter').value='all';$('updateStatus').textContent='';render();});}
  function render(){renderGrades();const visible=filtered(),sum=M.summary(visible);$('studentCount').textContent=sum.count;$('startedCount').textContent=sum.started+' have started practice';$('averageProgress').textContent=sum.average+'%';$('attentionCount').textContent=sum.attention;$('attentionNote').textContent=sum.notStarted+' not started · '+(sum.attention-sum.notStarted)+' need a closer look';$('finisherCount').textContent=sum.complete;$('gradeEyebrow').textContent=grade==='all'?'ALL GRADES':'GRADE '+grade;$('listDescription').textContent=({least:'Students with the least progress appear first.',most:'Students with the most progress appear first.',attention:'Practice gaps, check patterns, and review needs come first.',name:'Students are listed alphabetically.'})[$('sortBy').value];$('rowsView').setAttribute('aria-pressed',String(view==='rows'));$('tilesView').setAttribute('aria-pressed',String(view==='tiles'));$('studentRows').className='studentRows '+(view==='tiles'?'tileView':'');document.querySelector('.listHeader').hidden=view==='tiles';$('emptyState').hidden=visible.length>0;$('simulateUpdate').disabled=!visible.some(s=>M.ops.some(p=>s.operations[p].milestones<s.operations[p].total*4));$('studentRows').innerHTML=visible.map((s,i)=>{const status=M.support(s),progress=M.overall(s),initial=s.name[0],count=M.trophyCount(s);return `<button class="studentRow ${s.id===lastUpdated?'justUpdated':''}" data-student="${s.id}" aria-label="Open report for ${s.name}, grade ${s.grade}, ${progress}% progression"><span class="studentIdentity"><span class="rank">${i+1}</span><span class="avatar avatar${s.grade%4}">${initial}</span><span><strong>${s.name}</strong><small>Grade ${s.grade} · ${schoolName(s)}</small><span class="statusPill ${status.key}">${status.label}</span></span></span><span class="overallBlock"><span><strong>${progress}%</strong><small>${count} / 5 trophies</small></span>${bar(progress,s.name+' overall progression','overallTrack')}</span><span class="fiveMini">${M.paths.map(p=>smallPath(s,p)).join('')}</span><span class="nextStep"><span>${M.nextStep(s)}</span><b>View report ↗</b></span></button>`;}).join('');$('studentRows').querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>openReport(b.dataset.student));}
  function history(s){const current=M.overall(s),values=[.2,.38,.52,.67,.81,1].map(n=>Math.round(current*n)),points=values.map((v,i)=>(35+i*84)+','+(130-v)).join(' ');return `<figure class="historyChart"><figcaption>Illustrative progression over six weeks</figcaption><svg viewBox="0 0 500 155" role="img" aria-label="Example progression: ${values.join(', ')} percent"><path d="M35 30H470 M35 80H470 M35 130H470" fill="none" stroke="#d7d9ea" stroke-dasharray="4 5"/><polyline points="${points}" fill="none" stroke="#7653b5" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${35+i*84}" cy="${130-v}" r="5" fill="#7653b5"/><text x="${35+i*84}" y="150" text-anchor="middle">W${i+1}</text>`).join('')}</svg><span>Example history only. Live dates and results are not connected.</span></figure>`;}
  function pathwayReport(s,p){const trophy=M.hasTrophy(s,p),score=M.percentage(s,p);if(p==='mixed')return `<article class="reportPath"><div><h3>✦ Mixed</h3><strong>${score}%</strong></div>${bar(score,'Mixed check progression')}<p>${s.mixed.passes} / 3 passing mixed checks · ${s.mixed.retained?'Retention span met':'Seven-day retention span still required'}</p><p>${M.ops.filter(op=>M.hasTrophy(s,op)).length} / 4 operation trophies earned</p><span>${trophy?'🏆 Mixed trophy earned':'Mixed checks are separate from the shared fact bank.'}</span></article>`;const o=s.operations[p];return `<article class="reportPath"><div><h3>${M.symbols[p]} ${M.names[p]}</h3><strong>${score}%</strong></div>${bar(score,M.names[p]+' progression')}<p>${o.confirmed} / ${o.total} facts confirmed · ${Math.floor(100*o.milestones/(o.total*4))}% of practice milestones</p><p>${o.passes} / 3 passing checks · ${o.retained?'Retention span met':'Checks and retention still in progress'}</p><span>${trophy?'🏆 Operation trophy earned':o.refresh?o.refresh+' facts need refreshing':'Keep building independent success across days.'}</span></article>`;}
  function checkRows(s){if(!s.sessions)return'<tr><td colspan="5">No example checks yet. First check is the next step.</td></tr>';const p=M.ops.reduce((a,b)=>M.percentage(s,a)<M.percentage(s,b)?a:b),good=s.operations[p].passes>0||M.trophyCount(s)===5,counts=good?[24,28,31]:[17,18,18];return counts.map((correct,i)=>{const attempted=good&&i===2?32:correct+5,accuracy=correct/attempted,pass=correct>=30&&accuracy>=.95;return `<tr><td>${['Week 1 · Mon','Week 1 · Wed','Week 2 · Mon'][i]}</td><td>${M.names[p]}</td><td>${correct} / ${attempted}</td><td>${Math.round(100*accuracy)}%</td><td><span class="statusPill ${pass?'complete':'stalled'}">${pass?'Passed':'Practice needed'}</span></td></tr>`;}).join('');}
  function openReport(id){reportId=id;renderReport();$('studentReport').showModal();}
  function renderReport(){const s=students.find(s=>s.id===reportId);if(!s)return;const overall=M.overall(s);$('reportContent').innerHTML=`<div class="reportIdentity"><span class="avatar avatar${s.grade%4}">${s.name[0]}</span><div><h2 id="reportName">${s.name}</h2><p>Grade ${s.grade} · ${schoolName(s)} · ${s.className}</p><small>Fictional example · ${s.id}</small></div></div><div class="reportOverall"><span><strong>${overall}%</strong> toward five trophies</span><b>${M.trophyCount(s)} / 5 earned</b>${bar(overall,s.name+' overall progression')}</div><section class="reportNext"><span>NEXT BEST STEP</span><h3>${M.nextStep(s)}</h3><p>${s.sessions} example practice sessions · ${s.sessions?(s.lastPracticeDays?s.lastPracticeDays+' school days since practice':'Practiced today'):'Not started'}</p></section><div class="reportPathGrid">${M.paths.map(p=>pathwayReport(s,p)).join('')}</div>${history(s)}<section class="checkHistory"><h3>Example 90-second checks</h3><p>Illustrative recent results, not the complete record. Passing requires 30+ correct and 95% accuracy. Mixed also requires 7+ correct and 90% accuracy in every operation.</p><div class="tableScroll"><table><thead><tr><th>Example date</th><th>Pathway</th><th>Correct / attempted</th><th>Accuracy</th><th>Result</th></tr></thead><tbody>${checkRows(s)}</tbody></table></div></section><p class="reportBoundary">This report is a visual preview. No real student identity, assessment, attendance, or intervention record has been loaded.</p>`;}
  $('allGrades').onclick=()=>{grade='all';$('schoolFilter').value='all';render();};for(const id of ['schoolFilter','supportFilter','sortBy'])$(id).onchange=render;$('studentSearch').oninput=render;$('rowsView').onclick=()=>{view='rows';render();};$('tilesView').onclick=()=>{view='tiles';render();};$('closeReport').onclick=()=>$('studentReport').close();
  $('simulateUpdate').onclick=()=>{const before=filtered(),target=before.find(s=>M.ops.some(p=>s.operations[p].milestones<s.operations[p].total*4));if(!target)return;const position=before.findIndex(s=>s.id===target.id)+1,old=M.overall(target);M.update(target);lastUpdated=target.id;render();const now=filtered().findIndex(s=>s.id===target.id)+1;$('updateStatus').textContent='Example update: '+target.name+' moved from '+old+'% to '+M.overall(target)+'%. '+(now?'Position '+position+' → '+now+' in the current view.':'Current filters now hide this student.')+' Your player progress is unchanged.';};
  $('resetExamples').onclick=()=>{students=M.createStudents();lastUpdated=null;$('updateStatus').textContent='Example students reset. Your player progress is unchanged.';render();};render();
})();
